use std::collections::HashMap;

fn two_sum(nums: Vec<i32>, target: i32) -> Option<(usize, usize)> {
    // Map each value to its earliest index.
    let mut seen: HashMap<i32, usize> = HashMap::new();
    // We'll keep track of the lexicographically smallest valid pair (i,j).
    let mut best: Option<(usize, usize)> = None;

    for (j, &v_j) in nums.iter().enumerate() {
        // Compute complement = target - v_j in a checked way to avoid overflow.
        if let Some(complement) = target.checked_sub(v_j) {
            if let Some(&i) = seen.get(&complement) {
                // Make sure it's a distinct pair with i < j.
                if i < j {
                    let candidate = (i, j);
                    // Update best if we don't have one yet,
                    // or if this candidate is lexicographically smaller.
                    if best.map_or(true, |(bi, bj)| {
                        candidate.0 < bi || (candidate.0 == bi && candidate.1 < bj)
                    }) {
                        best = Some(candidate);
                    }
                }
            }
        }
        // Record the current value's index if it's the first time we see it.
        seen.entry(v_j).or_insert(j);
    }

    best
}

fn main() {
    let nums = vec![2, 7, 11, 15];
    let target = 9;
    assert_eq!(two_sum(nums, target), Some((0, 1)));

    let nums = vec![3, 2, 4];
    let target = 6;
    assert_eq!(two_sum(nums, target), Some((1, 2)));

    let nums = vec![3, 3];
    let target = 6;
    assert_eq!(two_sum(nums, target), Some((0, 1)));

    let nums = vec![1, i32::MAX, -1];
    let target = 0;
    // The pair (1, 2) sums to i32::MAX + (-1) which is still in range,
    // but no other pair sums to 0.
    assert_eq!(two_sum(nums, target), Some((1, 2)));

    // No valid pair:
    let nums = vec![1, 2, 3];
    let target = 7;
    assert_eq!(two_sum(nums, target), None);
}